def name_operands(region,address,operation):
 if region!='Station' or address not in FUNCTIONS:return operation
 for value,name in ((0x788D,'VariantPanelState.ItemIndex'),(0x78D7,'VariantPanelState.RefreshPending'),(0x78DC,'VariantPanelState.CadenceMask'),
  (0x7942,'VariantPanelState.ResumeRequired'),(0x9A89,'MenuCommandState.PeriodicCall'),(0x9E78,'ActiveItemState.Active'),(0x6307,'StationState.PointerXY')):
  operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 operation=operation.replace('LD A, #11','LD A, @SystemNameConst.MapPage').replace('LD A, #10','LD A, @StationIrqConst.StationPage')
 operation=operation.replace('CALL #C781','CALL @Map.PrepareVariantResources.Entry').replace('CALL #C677','CALL @Map.DrawVariantCluster.Entry')
 operation=operation.replace('CALL #C287','CALL @Station.DrawCaptionItem.Entry').replace('CALL #CCD4','CALL @Station.ResetBandMode.Entry')
 operation=operation.replace('LD HL, #9A58','LD HL, @Station.EmptyCallback.Entry')
 operation=operation.replace('LD DE, #788C','LD DE, @Station.DrawVariantPanel.Entry').replace('LD HL, #78D6','LD HL, @Station.UpdateVariantPanel.Entry')
 return operation
